package com.sharehope.newsletter.controller;import com.sharehope.newsletter.service.NewsletterService;import lombok.RequiredArgsConstructor;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.Instant;import java.util.*;
@RestController @RequestMapping("/api/public/newsletter") @RequiredArgsConstructor public class NewsletterUnsubscribeController{private final NewsletterService service;@Value("${app.newsletter.unsubscribe-secret:}")private String secret;
@PostMapping("/unsubscribe")public ResponseEntity<?> unsubscribe(@RequestBody Map<String,String> body){try{String email=body.get("email"),expires=body.get("expires"),signature=body.get("signature");if(secret.isBlank()||email==null||expires==null||signature==null||Instant.ofEpochSecond(Long.parseLong(expires)).isBefore(Instant.now()))return ResponseEntity.badRequest().build();Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));String expected=HexFormat.of().formatHex(mac.doFinal((email+"."+expires).getBytes(StandardCharsets.UTF_8)));if(!MessageDigest.isEqual(expected.getBytes(StandardCharsets.UTF_8),signature.getBytes(StandardCharsets.UTF_8)))return ResponseEntity.status(403).build();service.unsubscribe(email);return ResponseEntity.noContent().build();}catch(Exception e){return ResponseEntity.badRequest().build();}}}
